#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        // suffix: p[n-y .. n-1]
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        // middle: p[x .. n-y-1]
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        // prefix: p[0 .. x-1]
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    // Place elements 1..n in positions 0..n-1
    for(int placed=0; placed<n; placed++){
        // Find where (placed+1) currently is
        int pos = -1;
        for(int i=placed;i<n;i++){
            if(p[i]==placed+1){ pos=i; break; }
        }
        if(pos==placed) continue; // already correct

        // We want to move p[pos] to position 'placed'
        // Strategy: use one operation to move it to the front of the unsorted portion
        // 
        // If we set x = placed, y = n - pos:
        //   prefix = p[0..placed-1], suffix = p[pos..n-1], middle = p[placed..pos-1]
        //   result = [p[pos..n-1] | p[placed..pos-1] | p[0..placed-1]]
        //   Element placed+1 (at p[pos]) goes to position 0, but we want it at position 'placed'
        //
        // Better: if placed > 0, we can do x=placed, y=n-pos where x+y < n requires placed+n-pos < n => placed < pos (true since pos > placed)
        // Result: [p[pos..n-1], p[placed..pos-1], p[0..placed-1]]
        // Element is now at position 0, not placed.
        //
        // Alternative: two-step. First bring element to last position, then bring last to 'placed'.

        // Step 1: bring p[pos] to position (n-1) if it's not already there
        if(pos < n-1){
            // x = pos+1, y = n-1-pos. x+y = n, need < n. So use middle of size >=1.
            // x = 1, y = n-1-pos. x+y = n-pos. Need n-pos < n => pos > 0. True since pos > placed >= 0 and pos != placed.
            // But if pos == 0, placed must be < 0 which can't happen. Actually pos > placed >= 0 so pos >= 1.
            int x = 1, y = n-1-pos;
            if(x+y<n && y>0){
                apply_op(x, y);
                // p[0] moved to end, suffix p[pos+1..n-1] moved to front
                // Element was at pos, now at pos-1 (since one element removed from front, but suffix moved)
                // Actually let me just re-find it
                for(int i=0;i<n;i++) if(p[i]==placed+1){ pos=i; break; }
            }
        }
        if(pos==placed) continue;
        // Now element at pos. Use x=placed+1, y=n-pos, need placed+1+n-pos<n => placed+1<pos, i.e., placed<pos-1... 
        // Just do: x=placed, y=n-pos if placed>0
        if(placed==0){ int y=n-pos; if(y>0 && y<n-1){ apply_op(1,y); for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;} if(pos==0) continue;}}
        if(pos>placed && placed<n-1 && n-pos>0 && placed+(n-pos)<n){ apply_op(placed,n-pos); }
        // re-find
        for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;
        if(pos>placed){ apply_op(placed+1, n-pos); }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
